import { defineDriver, DriverError, retryableStatus, type CallContext } from "@sanoma-ai/workflows";
import { z } from "zod";
import { resendOps } from "./connector.ts";
// Generated by `pnpm run generate` (openapi-ts.config.ts); never edited by hand.
import { client as generated } from "./generated/client.gen.ts";
import { createClient } from "./generated/client/index.ts";
import {
  broadcastsCreate,
  broadcastsGet,
  broadcastsSend,
  domainsCreate,
  domainsGet,
  domainsList,
  domainsRemove,
  domainsVerify,
  emailsSend,
} from "./generated/index.ts";
import { type ApiDomain, type DomainApi, domainOperations } from "./domains.ts";

export interface ResendDriverOptions {
  /** How long one request may take before it fails, retryable. Default 15 seconds. */
  timeoutMs?: number;
}

/** The environment variables the driver reads, on every call. */
const env = z.object({
  RESEND_API_KEY: z.string().describe("an API key: a full-access one to manage domains, else sending access will do"),
});

/** Resend's error body. The spec declares none; the docs give `{ statusCode, name, message }`. */
const errorBody = z
  .object({ name: z.string().optional().catch(undefined), message: z.string().optional().catch(undefined) })
  .catch({});

/**
 * The DriverError for a request that failed. The client hands its error interceptor what went
 * wrong, the response once Resend answered, and the request once it was built.
 */
function failure(op: string, timeoutMs: number) {
  return (error: unknown, response: Response | undefined, request: Request | undefined): DriverError => {
    if (!request) {
      return new DriverError(`resend: ${op} could not build its request`, { retryable: false, cause: error });
    }
    if (!response) {
      // No reply at all (the timeout, a dropped connection): the call may be tried again.
      const timedOut = error instanceof Error && error.name === "TimeoutError";
      return new DriverError(`resend: ${op} ${timedOut ? `timed out after ${timeoutMs} ms` : "got no reply"}`, {
        retryable: true,
        cause: error,
      });
    }
    const { ok, status, statusText } = response;
    // A body that could not be read (cut off, or the timeout fired while reading it) leaves the
    // status to decide; a 2xx whose body is not JSON is no answer to retry.
    const cutOff = error instanceof Error && !(error instanceof SyntaxError);
    if (ok) {
      return new DriverError(
        `resend: ${op} replied ${status} with ${cutOff ? "a body cut off" : "a body that is not JSON"}`,
        { retryable: cutOff, status, cause: error },
      );
    }
    const { name, message } = cutOff ? {} : errorBody.parse(error);
    // A sending-only key answers anything but a send so.
    if (status === 401 && name === "restricted_api_key") {
      return new DriverError(
        `resend: ${op} needs a full-access API key in RESEND_API_KEY: ${message ?? "this key may only send emails"}`,
        { retryable: false, status, vendorCode: name },
      );
    }
    // A daily or monthly quota does not lift in the seconds a retry waits; a 409
    // `concurrent_idempotent_requests` is another request with this key still in flight, and
    // `resource_locked` another request on the same resource.
    const retryable =
      (retryableStatus(status) && !name?.endsWith("_quota_exceeded")) ||
      (status === 409 && (name === "concurrent_idempotent_requests" || name === "resource_locked"));
    return new DriverError(`resend: ${op} failed (${status}): ${message ?? statusText}`, {
      retryable,
      status,
      ...(name === undefined ? {} : { vendorCode: name }),
    });
  };
}

/** The broadcast or email in a reply Resend accepted: the spec leaves its id optional, and a proxy may answer instead. */
function replied<T extends { id?: string }>(op: string, reply: { data: T; response: Response }): T & { id: string } {
  if (reply.data?.id) return reply.data as T & { id: string };
  const { status } = reply.response;
  throw new DriverError(`resend: ${op} replied ${status} without an id`, { retryable: false, status });
}

/** The sender, the input's `from` (unless empty): Resend requires one. */
function senderOf(op: string, from: string | undefined): string {
  if (from) return from;
  throw new DriverError(
    `resend: ${op} needs \`from\` in its input, a sender on a domain verified in Resend (for sign-in codes, the config's \`login.from\`)`,
    { retryable: false },
  );
}

/** A request whose 404 means no such domain: `undefined` then. */
async function absent<T>(request: Promise<T>): Promise<T | undefined> {
  try {
    return await request;
  } catch (error) {
    if (error instanceof DriverError && error.status === 404) return undefined;
    throw error;
  }
}

/**
 * Calls Resend's Broadcasts API, its one-email send and its domain API with the key in
 * `RESEND_API_KEY`, read on every call. The contract's `audience` is Resend's `segment_id`:
 * Resend renamed audiences to segments.
 */
export function resendDriver(options: ResendDriverOptions = {}) {
  const timeoutMs = options.timeoutMs ?? 15_000;

  /** A client for one call of `op`; `idempotent: false` sends no Idempotency-Key. */
  function client(op: string, call: CallContext, { idempotent = true } = {}) {
    const key = process.env.RESEND_API_KEY;
    if (!key) throw new DriverError("resend: RESEND_API_KEY is not set", { retryable: false });
    // The generated client's config (the spec's server, throwOnError), with this call's key and headers.
    const api = createClient({
      ...generated.getConfig(),
      auth: key,
      // Resend documents Idempotency-Key for emails only (kept 24 hours); it is sent in case
      // broadcasts honour it too.
      ...(idempotent && { headers: { "Idempotency-Key": call.idempotencyKey } }),
      fetch: (input, init) => fetch(input, { ...init, signal: AbortSignal.timeout(timeoutMs) }),
    });
    api.interceptors.error.use(failure(op, timeoutMs));
    return api;
  }

  /** Resend's domain API for one call of `op`. */
  function domainApi(op: string, call: CallContext): DomainApi {
    // No Idempotency-Key: one call makes several requests (a create and its verify; a replace's
    // delete and create), which must not share one, and Resend documents none for domains.
    const api = client(op, call, { idempotent: false });
    return {
      create: async (body) => {
        try {
          return { id: replied(op, await domainsCreate({ client: api, body })).id };
        } catch (error) {
          // Resend says so only in its message: "The `example.com` domain has been registered already."
          if (error instanceof DriverError && error.status === 403 && /registered already/i.test(error.message)) {
            return undefined;
          }
          throw error;
        }
      },
      list: async (after) => {
        const { data } = await domainsList({ client: api, query: { limit: 100, ...(after && { after }) } });
        const items = data?.data ?? [];
        return {
          data: items.flatMap(({ id, name }) => (id && name ? [{ id, name }] : [])),
          next: data?.has_more === true ? items.at(-1)?.id : undefined,
        };
      },
      get: async (id) => {
        const reply = await absent(domainsGet({ client: api, path: { domain_id: id } }));
        return reply && (replied(op, reply) as ApiDomain);
      },
      verify: async (id) => {
        await domainsVerify({ client: api, path: { domain_id: id } });
      },
      remove: async (id) => {
        await absent(domainsRemove({ client: api, path: { domain_id: id } }));
      },
    };
  }
  const domains = (op: string, call: CallContext) => domainOperations(domainApi(`domain.${op}`, call));

  return defineDriver(
    resendOps,
    {
      domain: {
        import: (input, call) => domains("import", call).import(input),
        read: (input, call) => domains("read", call).read(input),
        plan: (input, call) => domains("plan", call).plan(input),
        create: (input, call) => domains("create", call).create(input),
        update: (input, call) => domains("update", call).update(input),
        delete: (input, call) => domains("delete", call).delete(input),
      },
      broadcast: {
        create: async (input, call) => {
          const from = senderOf("broadcast.create", input.from);
          const reply = await broadcastsCreate({
            client: client("broadcast.create", call),
            // `name` shows in Resend's dashboard only: it ties the broadcast to the call that made it.
            body: {
              segment_id: input.audience,
              from,
              subject: input.subject,
              html: input.html,
              name: call.idempotencyKey,
            },
          });
          return { id: replied("broadcast.create", reply).id };
        },
        send: async ({ id }, call) => {
          const api = client("broadcast.send", call);
          // A replay of a send whose reply was lost must not send again: send only a broadcast that
          // is still a draft or scheduled, and otherwise say where it is.
          const { status } = replied("broadcast.send", await broadcastsGet({ client: api, path: { id } }));
          if (status === "sent") return { id, status: "sent" as const };
          if (status === "queued") return { id, status: "queued" as const };
          if (status !== "draft" && status !== "scheduled") {
            throw new DriverError(
              `resend: broadcast.send: broadcast ${id} is ${status ?? "of no status"}, not sendable`,
              {
                retryable: false,
              },
            );
          }
          const reply = await broadcastsSend({ client: api, path: { id }, body: {} });
          // Resend replies with the id only: it accepts the broadcast and sends it in the background.
          return { id: replied("broadcast.send", reply).id, status: "queued" as const };
        },
      },
      emails: {
        // The call's idempotency key makes a retry within 24 hours return the first email's id
        // and send nothing; Resend refuses the key with another input (409, final).
        send: async ({ to, from, subject, html, text }, call) => {
          const reply = await emailsSend({
            client: client("emails.send", call),
            body: { to, from: senderOf("emails.send", from), subject, html, text },
          });
          return { id: replied("emails.send", reply).id };
        },
      },
    },
    { env },
  );
}
